solution.solution.cpp:
#include <cstddef>
#include <string>

// The bytes at data, as two hex digits each, separated by single spaces.
std::string hexDump(const void* data, std::size_t size)
{
    const std::string digits{ "0123456789ABCDEF" };
    const auto* bytes{ static_cast<const unsigned char*>(data) };

    std::string text{};
    for (std::size_t i{ 0 }; i < size; ++i)
    {
        if (i > 0) text += ' ';
        const unsigned char byte{ *(bytes + i) };
        text += digits[byte / 16];    // the high four bits
        text += digits[byte % 16];    // the low four bits
    }
    return text;
}

unitTests:
TEST("an int holding one thousand") {
    int score{ 1000 };
    CHECK_EQ(hexDump(&score, sizeof(score)), "E8 03 00 00");
}
TEST("a single character") {
    char grade{ 'A' };
    CHECK_EQ(hexDump(&grade, 1), "41");
}
TEST("minus one is every bit on") {
    int value{ -1 };
    CHECK_EQ(hexDump(&value, sizeof(value)), "FF FF FF FF");
}
TEST("a two-byte value") {
    unsigned short value{ 0xBEEF };
    CHECK_EQ(hexDump(&value, sizeof(value)), "EF BE");
}
TEST("bytes below sixteen keep their leading zero") {
    unsigned char bytes[3]{ 0x00, 0x0A, 0x10 };
    CHECK_EQ(hexDump(bytes, 3), "00 0A 10");
}
TEST("only part of an array") {
    unsigned char bytes[4]{ 0xDE, 0xAD, 0xBE, 0xEF };
    CHECK_EQ(hexDump(bytes, 2), "DE AD");
}
TEST("zero bytes is an empty string") {
    int value{ 5 };
    CHECK_EQ(hexDump(&value, 0), "");
}

